declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientDpopBoundAccessTokensAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientDpopBoundAccessTokensAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientDpopBoundAccessTokensAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isDpopBoundAccessTokens returns null on a freshly created holder.
     */
    public function testDpopBoundAccessTokensNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDpopBoundAccessTokensAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isDpopBoundAccessTokensAssigned());
        $this->assertNull($holder->isDpopBoundAccessTokens());
    }
}
class ImplWithTrustedClientDpopBoundAccessTokensAttributeHolderUnitTest
{
    use TrustedClientDpopBoundAccessTokensAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDpopBoundAccessTokensRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDpopBoundAccessTokens();
    }
}
